      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of depUses) {
    for (const nm of names) if (!cost.has(nm)) throw new Fail(`error: unknown task ${nm}`)
  }
  for (const nm of cost.keys()) deps.set(nm, new Set())
  for (const [name, ...ds] of depUses) for (const d of ds) deps.get(name).add(d)
  const names = [...cost.keys()].sort(cmp)
  const dl = new Map()
  for (const nm of names) dl.set(nm, [...deps.get(nm)].sort(cmp))
  return { names, cost, deps: dl }
}

/** Returns dependencies-first order; throws the cycle failure if any. */
function topo({ names, deps }) {
  const state = new Map()
  const order = []
  for (const root of names) {
    if (state.has(root)) continue
    const stack = [root]
    const idx = [0]
    state.set(root, 1)
    while (stack.length) {
      const top = stack[stack.length - 1]
      const ds = deps.get(top)
      const k = idx[idx.length - 1]
      if (k < ds.length) {
        idx[idx.length - 1]++
        const d = ds[k]
        const s = state.get(d)
        if (s === 1) {
          const cyc = stack.slice(stack.indexOf(d)).concat(d)
          throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
        }
        if (!s) {
          state.set(d, 1)
          stack.push(d)
          idx.push(0)
        }
      } else {
        state.set(top, 2)
        order.push(top)
        stack.pop()
        idx.pop()
      }
    }
  }
  return order
}

function times(g, order) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  let total = 0n
  for (const nm of order) {
    let s = 0n
    let d = 0
    for (const x of g.deps.get(nm)) {
      if (finish.get(x) > s) s = finish.get(x)
      if (depth.get(x) + 1 > d) d = depth.get(x) + 1
    }
    start.set(nm, s)
    const f = s + g.cost.get(nm)
    finish.set(nm, f)
    depth.set(nm, d)
    if (f > total) total = f
  }
  return { start, finish, depth, total }
}

function pack(g, order, workers) {
  const prio = new Map()
  const dependents = new Map(g.names.map((n) => [n, []]))
  for (const [n, ds] of g.deps) for (const d of ds) dependents.get(d).push(n)
  for (let i = order.length - 1; i >= 0; i--) {
    const nm = order[i]
    let best = 0n
    for (const x of dependents.get(nm)) if (prio.get(x) > best) best = prio.get(x)
    prio.set(nm, best + g.cost.get(nm))
  }
  const fin = new Map()
  const freeAt = new Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let remaining = g.names.length
  let t = 0n
  let makespan = 0n
  while (remaining > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const nm of g.names) {
        if (fin.has(nm)) continue
        if (!g.deps.get(nm).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (pick === null || prio.get(nm) > prio.get(pick)) pick = nm
      }
      if (pick === null) break
      const f = t + g.cost.get(pick)
      fin.set(pick, f)
      freeAt[w] = f
      runs[w].push(` ${pick}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    t = next
  }
  const out = runs.map((r, i) => `worker ${i}:${r.join('')}\n`)
  out.push(`makespan ${makespan}\n`)
  return out.join('')
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const g = parseGraph(readFileSync(0, 'utf8'))
  const order = topo(g)
  let out = ''
  if (args.mode === 'pack') {
    out = pack(g, order, args.workers)
  } else {
    const tm = times(g, order)
    if (args.mode === 'waves') {
      const waves = []
      for (const nm of g.names) (waves[tm.depth.get(nm)] ??= []).push(nm)
      waves.forEach((ws, k) => (out += `wave ${k}: ${ws.join(' ')}\n`))
    } else {
      for (const nm of g.names) {
        out += `${nm} start=${tm.start.get(nm)} finish=${tm.finish.get(nm)} depth=${tm.depth.get(nm)}\n`
      }
    }
    out += `total ${tm.total}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
