  }
  return { tokens, pos }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const src = readFileSync(0, 'utf8')
let res
try {
  res = scan(src)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  const cs = Array.from(src)
  let line = 1, col = 1
  for (let k = 0; k < e.i; k++) {
    if (cs[k] === '\n') { line++; col = 1 }
    else if (cs[k] === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
  }
  process.stderr.write(`error: ${line}:${col}: ${e.reason}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const [[l, c], kind, body] of res.tokens) out += `${l}:${c} ${kind} ${body}\n`
} else {
  for (const k of KINDS) out += `${k} ${res.tokens.filter((t) => t[1] === k).length}\n`
  out += `total ${res.tokens.length}\n`
}
process.stdout.write(out)
