  if (!chs.length) return base.slice(rs, re)
  const res = []
  let p = rs
  for (const c of chs) {
    res.push(...base.slice(p, c.start), ...c.lines)
    p = c.end
  }
  res.push(...base.slice(p, re))
  return res
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

