  const first = all[k]
  const rs = first.start
  let re = first.end
  const group = [first]
  k++
  while (k < all.length && all[k].start <= re) {
    re = Math.max(re, all[k].end)
    group.push(all[k++])
  }
  if (rs > pos) {
