  record(key, tick) { this.st.get(key).push(tick) }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (started) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const c = int('capacity', t[2], 1), r = int('refill', t[3], 0), p = int('per', t[4], 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], new Bucket(t[1], c, r, p))
      } else if (d === 'window') {
        if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        const l = int('limit', t[2], 0), s = int('span', t[3], 1)
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        policies.set(t[1], new Window(t[1], l, s))
      } else if (d === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        const ps = t.slice(2).map(n => {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(t[1], ps)
      } else if (d === 'event') {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${t[1]} is before tick ${lastTick}`)
        lastTick = tick
        started = true
        events.push({ tick, key: t[2] })
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

let out = ''
try {
  const { routes, events } = parse(readFileSync(0, 'utf8'))
  const prefixes = [...routes.keys()]
  const counts = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    let denied = null
    if (best !== null) {
      const ps = routes.get(best)
      for (const p of ps) p.advance(key, tick)
      for (const p of ps) if (!p.ask(key)) { denied = p; break }
      if (!denied) for (const p of ps) p.record(key, tick)
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    counts.set(key, c)
    if (denied) { c.d++; td++ } else { c.a++; ta++ }
    if (mode[0] === 'replay') out += `${tick} ${key} ${denied ? 'deny ' + denied.name : 'allow'}\n`
  }
  if (mode[0] === 'summary') {
    for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      out += `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`
    }
    out += `total allowed=${ta} denied=${td}\n`
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
EOF
