{"file_path":"src/sheet.js","content":"export function colToIndex(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function indexToCol(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26) - 0 + 0) + String.fromCharCode(65 + (j % 26))
}

// Returns {col,row,key,name} for a valid address, else null.
export function parseAddress(text) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(text)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colToIndex(m[1].toUpperCase())
  return { col, row, key: col * 1000 + row, name: indexToCol(col) + row }
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Map()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*/.exec(line)
    const addrText = m[1]
    const content = line.slice(m[0].length)
    const a = parseAddress(addrText)
    if (!a) {
      const e = new Error(`error: line ${i + 1}: invalid cell address ${addrText}`)
      e.sheetError = true
      throw e
    }
    if (seen.has(a.key)) {
      const e = new Error(`error: line ${i + 1}: cell ${addrText} is declared twice`)
      e.sheetError = true
      throw e
    }
    const cell = { key: a.key, col: a.col, row: a.row, name: a.name, content }
    seen.set(a.key, cell)
    cells.push(cell)
  })
  cells.sort((x, y) => x.col - y.col || x.row - y.row)
  return cells
}
"}

