      const c = this.peek()
      if (c === '}') { this.i++; return tbl }
      if (c !== ',') fail('unterminated inline table')
      this.i++
    }
  }
}

const P = (arr) => arr.join('.')

// Step into a node as a table for walking; arrays of tables use their last element.
function asWalkable(node, path) {
  if (node.t === 'table') return node
  if (node.t === 'array' && node.aot) return node.items[node.items.length - 1]
  return fail(`${P(path)} is not a table`)
}

function walk(tbl, base, names) {
  let cur = tbl
  const path = base.slice()
  for (const n of names) {
    path.push(n)
    let next = cur.map.get(n)
    if (!next) { next = newTable(); cur.map.set(n, next) }
    cur = asWalkable(next, path)
  }
  return cur
}

function assign(tbl, base, names, value) {
  const cur = walk(tbl, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (cur.map.has(last)) fail(`key ${P(base.concat(names))} is defined twice`)
  cur.map.set(last, value)
