const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

class Parser {
  constructor(line) { this.s = line; this.i = 0 }
  peek() { return this.s[this.i] }
  atEnd() { return this.i >= this.s.length }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atLineEnd() { const c = this.peek(); return c === undefined || c === '#' || c === ';' }

  quoted() {
    const q = this.s[this.i++]
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      if (this.atEnd()) fail('unterminated string')
      const c = this.s[this.i++]
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (this.atEnd()) fail('unterminated string')
      const e = this.s[this.i++]
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, e)) out += simple[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + String.fromCodePoint(this.s.codePointAt(this.i - 1)))
    }
  }

  name() {
    this.ws()
    const c = this.peek()
    if (c === '"' || c === "'") return this.quoted()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.peek())) this.i++
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = [this.name()]
    for (;;) {
      this.ws()
      if (this.peek() !== '.') return names
      this.i++
      names.push(this.name())
    }
  }

  value(prefix) {
    this.ws()
    const c = this.peek()
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: Number(w.replaceAll('_', '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(w)) {
      return { t: 'float', v: Number(w.replaceAll('_', '')) }
    }
    return fail('invalid value ' + w)
  }

  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atLineEnd()) fail('unterminated array')
      if (this.peek() === ']') { this.i++; return { t: 'array', items, aot: false } }
      items.push(this.value(prefix))
      this.ws()
      if (this.atLineEnd()) fail('unterminated array')
      const c = this.peek()
      if (c === ',') this.i++
      else if (c !== ']') fail('unterminated array')
    }
  }

  inline(prefix) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atLineEnd()) fail('unterminated inline table')
    if (this.peek() === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atLineEnd()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(prefix.concat(names))
      assign(tbl, prefix, names, v)
      this.ws()
      if (this.atLineEnd()) fail('unterminated inline table')
      const c = this.peek()
      if (c === '}') { this.i++; return tbl }
      if (c !== ',') fail('unterminated inline table')
      this.i++
    }
  }
}

const P = (arr) => arr.join('.')

// Step into a node as a table for walking; arrays of tables use their last element.
function asWalkable(node, path) {
  if (node.t === 'table') return node
  if (node.t === 'array' && node.aot) return node.items[node.items.length - 1]
  return fail(`${P(path)} is not a table`)
}

function walk(tbl, base, names) {
  let cur = tbl
  const path = base.slice()
  for (const n of names) {
    path.push(n)
    let next = cur.map.get(n)
    if (!next) { next = newTable(); cur.map.set(n, next) }
    cur = asWalkable(next, path)
  }
  return cur
}

function assign(tbl, base, names, value) {
  const cur = walk(tbl, base, names.slice(0, -1))
  const last = names[names.length - 1]
  if (cur.map.has(last)) fail(`key ${P(base.concat(names))} is defined twice`)
  cur.map.set(last, value)
}

function header(root, names, isArray) {
  const cur = walk(root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  const path = P(names)
  const ex = cur.map.get(last)
  if (isArray) {
    if (!ex) {
      const t = newTable()
      cur.map.set(last, { t: 'array', items: [t], aot: true })
      return t
    }
    if (ex.t !== 'array' || !ex.aot) fail(`${path} is not an array of tables`)
    const t = newTable()
    ex.items.push(t)
    return t
  }
  if (!ex) {
    const t = newTable()
    t.explicit = true
    cur.map.set(last, t)
    return t
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.explicit) fail(`table ${path} is defined twice`)
  ex.explicit = true
  return ex
}

function parseDoc(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const p = new Parser(lines[n])
      p.ws()
      const c = p.peek()
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        p.i++
        const isArray = p.peek() === '['
        if (isArray) p.i++
        const names = p.dotted()
        p.ws()
        if (p.peek() !== ']') fail('unterminated table header')
        p.i++
        if (isArray) {
          if (p.peek() !== ']') fail('unterminated table header')
          p.i++
        }
        p.ws()
        if (!p.atLineEnd()) fail('trailing text after a table header')
        cur = header(root, names, isArray)
        curPath = names
      } else {
        const names = p.dotted()
        p.ws()
        if (p.peek() !== '=') fail('expected key = value')
        p.i++
        const v = p.value(curPath.concat(names))
        p.ws()
        if (!p.atLineEnd()) fail('trailing text after a value')
        assign(cur, curPath, names, v)
      }
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
  return root
}

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (node.t === 'table') {
    const ks = sortedKeys(node.map)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(node.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (node.t === 'array') {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(node.v)
}

function toKeys(node, path, out) {
  const kids = node.t === 'table'
    ? sortedKeys(node.map).map((k) => [path === null ? k : `${path}.${k}`, node.map.get(k)])
    : node.t === 'array' ? node.items.map((x, i) => [`${path}[${i}]`, x]) : []
  for (const [p, child] of kids) {
    out.push(`${p} ${child.t}`)
    toKeys(child, p, out)
  }
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const root = parseDoc(readFileSync(0, 'utf8'))
  let out
  if (mode === 'json') out = toJson(root, 0) + '\n'
  else {
    const lines = []
    toKeys(root, null, lines)
    out = lines.map((l) => l + '\n').join('')
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
}
"}

