const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const num = (v) => ({ k: 'n', v })
const err = (v) => ({ k: 'e', v })
const bool = (v) => ({ k: 'b', v })

function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const c = m[1].toUpperCase()
  const col = c.length === 1 ? c.charCodeAt(0) - 64 : 26 + (c.charCodeAt(0) - 65) * 26 + (c.charCodeAt(1) - 64)
  return { col, row, name: c + row }
}
const colName = (i) => (i <= 26 ? String.fromCharCode(64 + i) : String.fromCharCode(65 + Math.floor((i - 27) / 26)) + String.fromCharCode(65 + ((i - 27) % 26)))
const key = (col, row) => colName(col) + row

// ---- read sheet
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const t = lines[i].replace(/^[ \t]+/, '')
  if (t === '' || t[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(t)
  const a = parseAddr(m[1])
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${m[1]}\n`)
    process.exit(2)
  }
  if (cells.has(a.name)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.name} is declared twice\n`)
    process.exit(2)
  }
  cells.set(a.name, { a, content: m[2] })
}

// ---- formula parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[=<>^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

