    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function check(r) {
  const parts = [['path', r.path]]
  if (r.auth) parts.push(['userinfo', r.auth.userinfo], ['host', r.auth.host])
  parts.push(['query', r.query], ['fragment', r.fragment])
  for (const [name, v] of parts) {
    if (v !== null && /%(?![0-9A-Fa-f]{2})/.test(v)) throw new Fail(`the ${name} has a truncated percent-encoding`)
  }
}

function serialize(r) {
  let s = ''
  if (r.scheme !== null) s += r.scheme + ':'
  if (r.auth) {
    s += '//'
    if (r.auth.userinfo !== null) s += r.auth.userinfo + '@'
    s += r.auth.host
    if (r.auth.port !== null) s += ':' + r.auth.port
  }
  s += r.path
  if (r.query !== null) s += '?' + r.query
  if (r.fragment !== null) s += '#' + r.fragment
  return s
}

function normalize(r) {
  check(r)
  const o = {
    scheme: r.scheme === null ? null : lower(r.scheme),
    auth: null,
    path: pct(r.path),
    query: r.query === null ? null : pct(r.query),
    fragment: r.fragment === null ? null : pct(r.fragment),
  }
  if (r.auth) {
    let port = r.auth.port
    if (port === '' || (o.scheme !== null && port !== null && DEFAULT_PORT[o.scheme] === port)) port = null
    o.auth = { userinfo: r.auth.userinfo === null ? null : pct(r.auth.userinfo), host: lower(pct(r.auth.host)), port }
  }
  o.path = removeDots(o.path)
  if (o.auth && o.path === '') o.path = '/'
  return serialize(o)
}

function resolve(base, ref) {
  const b = parse(base)
  if (b.scheme === null) throw new Fail('the base has no scheme')
  const r = parse(ref)
  let t
  if (r.scheme !== null) t = { ...r, path: removeDots(r.path) }
  else if (r.auth) t = { ...r, scheme: b.scheme, path: removeDots(r.path) }
  else if (r.path === '') {
    t = { scheme: b.scheme, auth: b.auth, path: b.path, query: r.query !== null ? r.query : b.query, fragment: r.fragment }
  } else {
    let path
    if (r.path.startsWith('/')) path = r.path
    else if (b.auth && b.path === '') path = '/' + r.path
    else {
      const i = b.path.lastIndexOf('/')
      path = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path
    }
    t = { scheme: b.scheme, auth: b.auth, path: removeDots(path), query: r.query, fragment: r.fragment }
  }
  return normalize(t)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  for (let i = 0; i < lines.length; i++) {
    try {
      if (args[0] === 'normalize') out.push(normalize(parse(lines[i])))
      else {
        const sp = lines[i].indexOf(' ')
        if (sp < 0) throw new Fail('expected a base and a reference')
        out.push(resolve(lines[i].slice(0, sp), lines[i].slice(sp + 1)))
      }
    } catch (e) {
      if (!(e instanceof Fail)) throw e
      process.stderr.write(`error: line ${i + 1}: ${e.message}\n`)
      process.exit(2)
    }
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

main()
"}

