import { readFileSync } from 'node:fs'

const MODES = ['merge', 'merge2', 'regions']

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function changes(base, side, owner) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j, owner })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.owner - b.owner)

  const out = []
  let conflict = false
  let pos = 0
  let k = 0
  const stable = (upto) => {
    if (upto > pos) {
      if (mode === 'regions') out.push(`stable ${upto - pos}`)
      else out.push(...base.slice(pos, upto))
    }
  }
  const emit = (kind, resolved) => {
    if (mode === 'regions') out.push(`${kind} ${resolved.length}`)
    else out.push(...resolved)
  }
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs)
    pos = re
    const baseLines = base.slice(rs, re)
    if (group.length === 1) {
      const c = group[0]
      const side = c.owner === 0 ? mine : theirs
      emit(c.owner === 0 ? 'mine' : 'theirs', side.slice(c.ss, c.se))
      continue
    }
    const sideLines = (owner, doc) => {
      const cs = group.filter(c => c.owner === owner)
      if (!cs.length) return baseLines
      const minBs = Math.min(...cs.map(c => c.bs))
      const maxBe = Math.max(...cs.map(c => c.be))
      const first = cs[0], last = cs[cs.length - 1]
      return doc.slice(first.ss - (minBs - rs), last.se + (re - maxBe))
    }
    const a = sideLines(0, mine), b = sideLines(1, theirs)
    if (same(a, b)) emit('both', a)
    else if (same(a, baseLines)) emit('theirs', b)
    else if (same(b, baseLines)) emit('mine', a)
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${a.length} base=${baseLines.length} theirs=${b.length}`)
      else {
        out.push('<<<<<<< mine', ...a)
        if (mode === 'merge') out.push('||||||| base', ...baseLines)
        out.push('=======', ...b, '>>>>>>> theirs')
      }
    }
  }
  stable(base.length)
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}

main()
