{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isLetter = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isIdent = (c) => isLetter(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { depth++; advN(2) }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      advN(2)
      let v = ''
      while (i < n && s[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isLetter(c)) {
      let t = ''
      while (i < n && isIdent(s[i])) t += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(t) ? 'keyword' : 'ident', body: t })
      continue
    }
    if (isDigit(c)) {
      let t = ''
      const take = () => { t += adv() }
      const run = (ok) => {
        while (i < n) {
          if (ok(s[i])) take()
          else if (s[i] === '_' && ok(s[i + 1]) && t.length && ok(t[t.length - 1])) take()
          else break
        }
      }
      let bad = false
      const p = (s[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        take(); take()
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        if (!ok(s[i])) bad = true
        else run(ok)
      } else {
        run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) { take(); run(isDigit) }
        if (s[i] === 'e' || s[i] === 'E') {
          if (isDigit(s[i + 1]) || ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2]))) {
            take()
            if (!isDigit(s[i])) take()
            run(isDigit)
          }
        }
      }
      if (bad || isIdent(s[i])) {
        while (i < n && isIdent(s[i])) take()
        throw new ScanError(sl, sc, `invalid number ${t}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: t })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = s[i]
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch === '"') { adv(); break }
        if (ch !== '\\') { v += adv(); continue }
        const el = line, ec = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = s[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { v += simple[e]; adv(); continue }
        if (e === 'x') {
          if (isHex(s[i + 1]) && isHex(s[i + 2])) {
            v += String.fromCharCode(parseInt(s[i + 1] + s[i + 2], 16))
            advN(3)
            continue
          }
        } else if (e === 'u' && s[i + 1] === '{') {
          let j = i + 2, h = ''
          while (isHex(s[j])) h += s[j++]
          if (h && s[j] === '}' && parseInt(h, 16) <= 0x10ffff) {
            v += String.fromCodePoint(parseInt(h, 16))
            advN(j + 1 - i)
            continue
          }
        }
        throw new ScanError(el, ec, `invalid escape \\${e}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (s[i + 1] || '')
    if (PUNCT.includes(two)) {
      advN(2)
      tokens.push({ line: sl, col: sc, kind: 'punct', body: two })
      continue
    }
    if (PUNCT1.includes(c)) {
      adv()
