  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
