      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { depth++; advN(2) }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      advN(2)
      let v = ''
      while (i < n && s[i] !== '"') v += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
