{"description":"Write cli and run tests","command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_-]+$/
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (cands !== null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (t[0] === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
})
if (cands === null) fail('error: no candidates')

const continuing = new Set(cands)
const history = []
const out = []
let winner = null
let round = 0
for (;;) {
  round++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
  }
  history.push(counts)
  let exhausted = 0n
  for (const b of ballots) exhausted += b.count
  exhausted -= active
  const order = [...counts.keys()].sort((a, b) => {
    const d = counts.get(b) - counts.get(a)
    return d > 0n ? 1 : d < 0n ? -1 : a < b ? -1 : a > b ? 1 : 0
  })
  out.push(`round ${round}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${exhausted}`)
  if (active === 0n) break
  const top = order[0]
  if (counts.get(top) * 2n > active) { winner = top; break }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let tied = [...continuing].filter((c) => counts.get(c) === min)
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    let m = null
    for (const c of tied) { const v = history[r].get(c); if (m === null || v < m) m = v }
    tied = tied.filter((c) => history[r].get(c) === m)
  }
  const elim = tied.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
process.stdout.write((mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${round}\n`) + end + '\n')
EOF
node --test test/*.test.js 2>&1 | tail -8"}

